class ProductionTask extends DataClass implements Insertable<ProductionTask> {
  final String id;
  final String productId;
  final double mengeKg;

  /// Das Datum, für das der Auftrag geplant ist (Konvention: 00:00 Uhr lokal).
  final DateTime datum;

  /// Abteilung, in der dieser Task ausgeführt wird.
  /// Gespeichert als [Abteilung.dbValue].
  final String abteilung;

  /// Anlage, auf der dieser Auftrag läuft (optional).
  ///
  /// Wird beim Planen aus dem Prozessschritt übernommen. In Abteilungen mit
  /// mehreren parallelen Anlagen (Verpackung) bestimmt sie die Kapazitäts-
  /// spur; ein Umbelegen auf eine andere Anlage ändert nur dieses Feld
  /// (und ggf. die Abteilung, wenn die Ausweichanlage woanders steht).
  final String? maschineId;

  /// Bedarf, aus dem dieser Auftrag entstanden ist (optional).
  ///
  /// Über diese Verknüpfung weiß die Bedarfsliste, wie viel von der
  /// benötigten Menge schon eingeplant ist — ohne dass irgendwo ein
  /// Zähler mitgeführt werden muss, der aus dem Tritt geraten kann.
  /// Wird ein Auftrag gelöscht, ist der Bedarf automatisch wieder offen.
  final String? bedarfId;

  /// Geplante FERTIGWARE-Menge dieser Produktion in kg.
  ///
  /// Nur beim ERSTEN Auftrag einer Kette gesetzt (`parentTaskId == null`);
  /// die Folgeschritte tragen ihre jeweilige Eingangsmenge in `mengeKg`.
  /// Genau dieser Wert wird gegen den Bedarf gerechnet.
  final double? fertigMengeKg;

  /// Auftragszeilen aus dem Auftragsbestand, für die diese Produktion
  /// eingeplant wurde — als JSON-Liste (siehe `AuftragsBezug`).
  ///
  /// Wie [fertigMengeKg] nur an der Wurzel der Kette. Bewusst hier und
  /// nicht in einer eigenen Tabelle: Die Zuordnung lebt und stirbt mit der
  /// Produktion. Wird die Kette im Board gelöscht, sind die Zeilen im
  /// Auftragsbestand ohne weiteres Zutun wieder offen — und das Backup
  /// trägt die Zuordnung mit, ohne dass es davon wissen muss.
  final String? auftragsZeilen;

  /// Geplante Startzeit als "HH:MM"-String (z.B. "08:30"). Null, wenn der
  /// Task für den Tag geplant ist, aber keine feste Uhrzeit hat.
  final String? startZeit;

  /// Aus Skalierung berechnete Dauer, aber speicherbar, weil manuell
  /// übersteuerbar.
  final double geplanteDauerMinuten;
  final int geplanteMitarbeiter;

  /// Manuelle Reihenfolge innerhalb einer Abteilung an einem Tag.
  /// Kleinere Werte zuerst. Standard 0 (dann greift die Sekundär-Sortierung
  /// nach Startzeit/Dauer). Wird über Hoch/Runter im Tagesplan gesetzt.
  final int sortierung;

  /// Status des Auftrags. Erlaubte Werte (als Konstanten im Repo-Layer):
  /// 'geplant', 'in_arbeit', 'fertig', 'storniert'.
  final String status;

  /// Self-Referenz für automatisch erzeugte Vor-Tasks.
  /// Beispiel: Auftrag "Leberkäse Bratstraße" erzeugt vorgelagert
  /// "Leberkäse Wurstküche" und "Leberkäse Zerlegung" — alle mit
  /// parent_task_id auf den Bratstraßen-Task.
  final String? parentTaskId;
  final String? notizen;
  final DateTime createdAt;
  final DateTime updatedAt;
  final DateTime? deletedAt;
  const ProductionTask(
      {required this.id,
      required this.productId,
      required this.mengeKg,
      required this.datum,
      required this.abteilung,
      this.maschineId,
      this.bedarfId,
      this.fertigMengeKg,
      this.auftragsZeilen,
      this.startZeit,
      required this.geplanteDauerMinuten,
      required this.geplanteMitarbeiter,
      required this.sortierung,
      required this.status,
      this.parentTaskId,
      this.notizen,
      required this.createdAt,
      required this.updatedAt,
      this.deletedAt});
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['product_id'] = Variable<String>(productId);
    map['menge_kg'] = Variable<double>(mengeKg);
    map['datum'] = Variable<DateTime>(datum);
    map['abteilung'] = Variable<String>(abteilung);
    if (!nullToAbsent || maschineId != null) {
      map['maschine_id'] = Variable<String>(maschineId);
    }
    if (!nullToAbsent || bedarfId != null) {
      map['bedarf_id'] = Variable<String>(bedarfId);
    }
    if (!nullToAbsent || fertigMengeKg != null) {
      map['fertig_menge_kg'] = Variable<double>(fertigMengeKg);
    }
    if (!nullToAbsent || auftragsZeilen != null) {
      map['auftrags_zeilen'] = Variable<String>(auftragsZeilen);
    }
    if (!nullToAbsent || startZeit != null) {
      map['start_zeit'] = Variable<String>(startZeit);
    }
    map['geplante_dauer_minuten'] = Variable<double>(geplanteDauerMinuten);
    map['geplante_mitarbeiter'] = Variable<int>(geplanteMitarbeiter);
    map['sortierung'] = Variable<int>(sortierung);
    map['status'] = Variable<String>(status);
    if (!nullToAbsent || parentTaskId != null) {
      map['parent_task_id'] = Variable<String>(parentTaskId);
    }
    if (!nullToAbsent || notizen != null) {
      map['notizen'] = Variable<String>(notizen);
    }
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    if (!nullToAbsent || deletedAt != null) {
      map['deleted_at'] = Variable<DateTime>(deletedAt);
    }
    return map;
  }

