    if (!nullToAbsent || deletedAt != null) {
      map['deleted_at'] = Variable<DateTime>(deletedAt);
    }
    return map;
  }

  WeekSnapshotsCompanion toCompanion(bool nullToAbsent) {
    return WeekSnapshotsCompanion(
